package com.shopsphere;
import com.nimbusds.jose.jwk.source.ImmutableSecret;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import javax.crypto.SecretKey;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.oauth2.jwt.*;import org.springframework.stereotype.Service;
@Service public class JwtService {private final JwtEncoder encoder;private final JwtDecoder decoder;private final long accessMinutes;private final long refreshDays;public JwtService(@Value("${shopsphere.jwt.secret}")String secret,@Value("${shopsphere.jwt.access-minutes}")long accessMinutes,@Value("${shopsphere.jwt.refresh-days}")long refreshDays){byte[] bytes=Arrays.copyOf(secret.getBytes(StandardCharsets.UTF_8),32);SecretKey key=new SecretKeySpec(bytes,"HmacSHA256");encoder=new NimbusJwtEncoder(new ImmutableSecret<>(key));decoder=NimbusJwtDecoder.withSecretKey(key).macAlgorithm(MacAlgorithm.HS256).build();this.accessMinutes=accessMinutes;this.refreshDays=refreshDays;}public JwtDecoder decoder(){return decoder;}public String access(User u){return token(u,Duration.ofMinutes(accessMinutes),"access");}public String refresh(User u){return token(u,Duration.ofDays(refreshDays),"refresh");}private String token(User u,Duration ttl,String type){Instant now=Instant.now();JwtClaimsSet claims=JwtClaimsSet.builder().issuer("shopsphere-auth").issuedAt(now).expiresAt(now.plus(ttl)).subject(u.id().toString()).claim("email",u.email()).claim("role",u.role().name()).claim("type",type).build();return encoder.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),claims)).getTokenValue();}public Jwt validate(String token,String type){Jwt jwt=decoder.decode(token);if(!type.equals(jwt.getClaimAsString("type")))throw new JwtException("Invalid token type");return jwt;}public long accessSeconds(){return Duration.ofMinutes(accessMinutes).toSeconds();}}
